// Type: ResourceLine.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ResourceLine {
    pub part: Part,
    pub kind: u16,
    pub taken: bool,
    pub holder: Option<u64>,
    pub writer: Option<ResourceWriter>,
    pub writer_lost: bool,
}

// Record: ResourceLine.
impl Record for ResourceLine {
    type Limits = Limits;
    const TAIL: Path = paths::RESOURCE_LINE_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 499)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 499)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::write(field::Nested, &self.part, limits, out, paths::RESOURCE_LINE_PART)?;
        field::write(field::U16, &self.kind, limits, out, paths::RESOURCE_LINE_KIND)?;
        field::write(field::Boolean, &self.taken, limits, out, paths::RESOURCE_LINE_TAKEN)?;
        field::write(field::Optional { item: field::U64 }, &self.holder, limits, out, paths::RESOURCE_LINE_HOLDER)?;
        field::write(field::Optional { item: field::Nested }, &self.writer, limits, out, paths::RESOURCE_LINE_WRITER)?;
        field::write(field::Boolean, &self.writer_lost, limits, out, paths::RESOURCE_LINE_WRITER_LOST)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        Ok(Self {
            part: field::read(field::Nested, limits, reader, paths::RESOURCE_LINE_PART)?,
            kind: field::read(field::U16, limits, reader, paths::RESOURCE_LINE_KIND)?,
            taken: field::read(field::Boolean, limits, reader, paths::RESOURCE_LINE_TAKEN)?,
            holder: field::read(field::Optional { item: field::U64 }, limits, reader, paths::RESOURCE_LINE_HOLDER)?,
            writer: field::read(field::Optional { item: field::Nested }, limits, reader, paths::RESOURCE_LINE_WRITER)?,
            writer_lost: field::read(field::Boolean, limits, reader, paths::RESOURCE_LINE_WRITER_LOST)?,
        })
    }
}

