// Type: EndingFields.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum EndingFields {
    Task(EndingTaskFields),
    Done,
    Failed(EndingFailedFields),
    Cancelled(EndingCancelledFields),
    Withdrawn(EndingWithdrawnFields),
    Decided(EndingDecidedFields),
    Deleted,
}

// Record: EndingFields.
impl Record for EndingFields {
    type Limits = Limits;
    const TAIL: Path = paths::ENDING_FIELDS_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 560)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 560)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Task(value) => { field::put(out, &[0], paths::ENDING_FIELDS_TAG)?; value.write(limits, out) },
            Self::Done => field::put(out, &[1], paths::ENDING_FIELDS_TAG),
            Self::Failed(value) => { field::put(out, &[2], paths::ENDING_FIELDS_TAG)?; value.write(limits, out) },
            Self::Cancelled(value) => { field::put(out, &[3], paths::ENDING_FIELDS_TAG)?; value.write(limits, out) },
            Self::Withdrawn(value) => { field::put(out, &[4], paths::ENDING_FIELDS_TAG)?; value.write(limits, out) },
            Self::Decided(value) => { field::put(out, &[5], paths::ENDING_FIELDS_TAG)?; value.write(limits, out) },
            Self::Deleted => field::put(out, &[6], paths::ENDING_FIELDS_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::ENDING_FIELDS_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Task(EndingTaskFields::read(limits, reader)?)),
            1 => Ok(Self::Done),
            2 => Ok(Self::Failed(EndingFailedFields::read(limits, reader)?)),
            3 => Ok(Self::Cancelled(EndingCancelledFields::read(limits, reader)?)),
            4 => Ok(Self::Withdrawn(EndingWithdrawnFields::read(limits, reader)?)),
            5 => Ok(Self::Decided(EndingDecidedFields::read(limits, reader)?)),
            6 => Ok(Self::Deleted),
            7..=u8::MAX => Err(Problem { path: paths::ENDING_FIELDS_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

