// Type: DecideOn.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum DecideOn {
    Proposal(DecideProposal),
    Escalation(DecideEscalation),
}

// Record: DecideOn.
impl Record for DecideOn {
    type Limits = Limits;
    const TAIL: Path = paths::DECIDE_ON_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 884)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 884)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Proposal(value) => { field::put(out, &[0], paths::DECIDE_ON_TAG)?; value.write(limits, out) },
            Self::Escalation(value) => { field::put(out, &[1], paths::DECIDE_ON_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::DECIDE_ON_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Proposal(DecideProposal::read(limits, reader)?)),
            1 => Ok(Self::Escalation(DecideEscalation::read(limits, reader)?)),
            2..=u8::MAX => Err(Problem { path: paths::DECIDE_ON_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

