// Type: Operation.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Operation {
    Message(Message),
    Amend(Box<Amend>),
    Cancel(Cancel),
    Release(Release),
    Stop(Stop),
    MoveTask(Move),
}

// Record: Operation.
impl Record for Operation {
    type Limits = Limits;
    const TAIL: Path = paths::OPERATION_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 942)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 942)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Message(value) => { field::put(out, &[0], paths::OPERATION_TAG)?; value.write(limits, out) },
            Self::Amend(value) => { field::put(out, &[1], paths::OPERATION_TAG)?; value.write(limits, out) },
            Self::Cancel(value) => { field::put(out, &[2], paths::OPERATION_TAG)?; value.write(limits, out) },
            Self::Release(value) => { field::put(out, &[3], paths::OPERATION_TAG)?; value.write(limits, out) },
            Self::Stop(value) => { field::put(out, &[4], paths::OPERATION_TAG)?; value.write(limits, out) },
            Self::MoveTask(value) => { field::put(out, &[5], paths::OPERATION_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::OPERATION_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Message(Message::read(limits, reader)?)),
            1 => Ok(Self::Amend(Box::new(Amend::read(limits, reader)?))),
            2 => Ok(Self::Cancel(Cancel::read(limits, reader)?)),
            3 => Ok(Self::Release(Release::read(limits, reader)?)),
            4 => Ok(Self::Stop(Stop::read(limits, reader)?)),
            5 => Ok(Self::MoveTask(Move::read(limits, reader)?)),
            6..=u8::MAX => Err(Problem { path: paths::OPERATION_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

