// Record: ProposeAction.
impl Record for ProposeAction {
    type Limits = Limits;
    const TAIL: Path = paths::PROPOSE_ACTION_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1017)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1017)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Batch(value) => { field::put(out, &[0], paths::PROPOSE_ACTION_TAG)?; value.write(limits, out) },
            Self::Amendment(value) => { field::put(out, &[1], paths::PROPOSE_ACTION_TAG)?; value.write(limits, out) },
            Self::Settings(value) => { field::put(out, &[2], paths::PROPOSE_ACTION_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::PROPOSE_ACTION_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Batch(ProposeBatch::read(limits, reader)?)),
            1 => Ok(Self::Amendment(Box::new(ProposeAmendment::read(limits, reader)?))),
            2 => Ok(Self::Settings(ProposeSettings::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::PROPOSE_ACTION_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

