    const TAIL: Path = paths::SCOPE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1369)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1369)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Project(value) => { field::put(out, &[0], paths::SCOPE_TAG)?; value.write(limits, out) },
            Self::Deployment => field::put(out, &[1], paths::SCOPE_TAG),
            Self::Own => field::put(out, &[2], paths::SCOPE_TAG),
        }
    }

