// Type: ReadNone.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ReadNone {
    Unknown,
    Refused,
    Gone,
    Busy,
    SignedOut,
    TooLarge(TurnTooLarge),
    Malformed,
    TooLinked(ReadTooLinked),
}

// Record: ReadNone.
impl Record for ReadNone {
    type Limits = Limits;
    const TAIL: Path = paths::READ_NONE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1483)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1483)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Unknown => field::put(out, &[0], paths::READ_NONE_TAG),
            Self::Refused => field::put(out, &[1], paths::READ_NONE_TAG),
            Self::Gone => field::put(out, &[2], paths::READ_NONE_TAG),
            Self::Busy => field::put(out, &[3], paths::READ_NONE_TAG),
            Self::SignedOut => field::put(out, &[4], paths::READ_NONE_TAG),
            Self::TooLarge(value) => { field::put(out, &[5], paths::READ_NONE_TAG)?; value.write(limits, out) },
            Self::Malformed => field::put(out, &[6], paths::READ_NONE_TAG),
            Self::TooLinked(value) => { field::put(out, &[7], paths::READ_NONE_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::READ_NONE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Unknown),
            1 => Ok(Self::Refused),
            2 => Ok(Self::Gone),
            3 => Ok(Self::Busy),
            4 => Ok(Self::SignedOut),
            5 => Ok(Self::TooLarge(TurnTooLarge::read(limits, reader)?)),
            6 => Ok(Self::Malformed),
            7 => Ok(Self::TooLinked(ReadTooLinked::read(limits, reader)?)),
            8..=u8::MAX => Err(Problem { path: paths::READ_NONE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

