// Type: ReadAnswer.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ReadAnswer {
    NotServed(NotServed),
    Value(Owned),
    None(ReadAnswerNone),
}

// Record: ReadAnswer.
impl Record for ReadAnswer {
    type Limits = Limits;
    const TAIL: Path = paths::READ_ANSWER_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1485)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1485)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::NotServed(value) => { field::put(out, &[0], paths::READ_ANSWER_TAG)?; value.write(limits, out) },
            Self::Value(value) => { field::put(out, &[1], paths::READ_ANSWER_TAG)?; value.write(limits, out) },
            Self::None(value) => { field::put(out, &[2], paths::READ_ANSWER_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::READ_ANSWER_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::NotServed(NotServed::read(limits, reader)?)),
            1 => Ok(Self::Value(Owned::read(limits, reader)?)),
            2 => Ok(Self::None(ReadAnswerNone::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::READ_ANSWER_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

