// Type: HistoryChange.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum HistoryChange {
    Cancelled,
    Released,
    Amended,
    Moved,
    Proposed,
    ProposalPassed,
    ProposalAccepted,
    ProposalRejected,
    ProposalWithdrawn,
    Concluded,
    Made,
}

// Record: HistoryChange.
impl Record for HistoryChange {
    type Limits = Limits;
    const TAIL: Path = paths::HISTORY_CHANGE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1838)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1838)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Cancelled => field::put(out, &[0], paths::HISTORY_CHANGE_TAG),
            Self::Released => field::put(out, &[1], paths::HISTORY_CHANGE_TAG),
            Self::Amended => field::put(out, &[2], paths::HISTORY_CHANGE_TAG),
            Self::Moved => field::put(out, &[3], paths::HISTORY_CHANGE_TAG),
            Self::Proposed => field::put(out, &[4], paths::HISTORY_CHANGE_TAG),
            Self::ProposalPassed => field::put(out, &[5], paths::HISTORY_CHANGE_TAG),
            Self::ProposalAccepted => field::put(out, &[6], paths::HISTORY_CHANGE_TAG),
            Self::ProposalRejected => field::put(out, &[7], paths::HISTORY_CHANGE_TAG),
            Self::ProposalWithdrawn => field::put(out, &[8], paths::HISTORY_CHANGE_TAG),
            Self::Concluded => field::put(out, &[9], paths::HISTORY_CHANGE_TAG),
            Self::Made => field::put(out, &[10], paths::HISTORY_CHANGE_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::HISTORY_CHANGE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Cancelled),
            1 => Ok(Self::Released),
            2 => Ok(Self::Amended),
            3 => Ok(Self::Moved),
            4 => Ok(Self::Proposed),
            5 => Ok(Self::ProposalPassed),
            6 => Ok(Self::ProposalAccepted),
            7 => Ok(Self::ProposalRejected),
            8 => Ok(Self::ProposalWithdrawn),
            9 => Ok(Self::Concluded),
            10 => Ok(Self::Made),
            11..=u8::MAX => Err(Problem { path: paths::HISTORY_CHANGE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

