// Type: ParameterDocument.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ParameterDocument {
    Number(ParameterDocumentNumber),
    Bytes(ParameterDocumentBytes),
    Resource(ParameterDocumentResource),
}

// Record: ParameterDocument.
impl Record for ParameterDocument {
    type Limits = Limits;
    const TAIL: Path = paths::PARAMETER_DOCUMENT_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1848)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1848)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Number(value) => { field::put(out, &[0], paths::PARAMETER_DOCUMENT_TAG)?; value.write(limits, out) },
            Self::Bytes(value) => { field::put(out, &[1], paths::PARAMETER_DOCUMENT_TAG)?; value.write(limits, out) },
            Self::Resource(value) => { field::put(out, &[2], paths::PARAMETER_DOCUMENT_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::PARAMETER_DOCUMENT_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Number(ParameterDocumentNumber::read(limits, reader)?)),
            1 => Ok(Self::Bytes(ParameterDocumentBytes::read(limits, reader)?)),
            2 => Ok(Self::Resource(ParameterDocumentResource::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::PARAMETER_DOCUMENT_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

