// Type: Setting.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Setting {
    Charter(SettingNumber),
    Template(SettingNumber),
    Policy(SettingNumber),
    Rules,
    Application(ApplicationSetting),
    ProjectPolicy(ProjectPolicySetting),
    Model(SettingNumber),
    Worker(SettingNumber),
    Provider(SettingNumber),
    Limits,
}

// Record: Setting.
impl Record for Setting {
    type Limits = Limits;
    const TAIL: Path = paths::SETTING_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1903)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1903)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Charter(value) => { field::put(out, &[0], paths::SETTING_TAG)?; value.write(limits, out) },
            Self::Template(value) => { field::put(out, &[1], paths::SETTING_TAG)?; value.write(limits, out) },
            Self::Policy(value) => { field::put(out, &[2], paths::SETTING_TAG)?; value.write(limits, out) },
            Self::Rules => field::put(out, &[3], paths::SETTING_TAG),
            Self::Application(value) => { field::put(out, &[4], paths::SETTING_TAG)?; value.write(limits, out) },
            Self::ProjectPolicy(value) => { field::put(out, &[5], paths::SETTING_TAG)?; value.write(limits, out) },
            Self::Model(value) => { field::put(out, &[6], paths::SETTING_TAG)?; value.write(limits, out) },
            Self::Worker(value) => { field::put(out, &[7], paths::SETTING_TAG)?; value.write(limits, out) },
            Self::Provider(value) => { field::put(out, &[8], paths::SETTING_TAG)?; value.write(limits, out) },
            Self::Limits => field::put(out, &[9], paths::SETTING_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::SETTING_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Charter(SettingNumber::read(limits, reader)?)),
            1 => Ok(Self::Template(SettingNumber::read(limits, reader)?)),
            2 => Ok(Self::Policy(SettingNumber::read(limits, reader)?)),
            3 => Ok(Self::Rules),
            4 => Ok(Self::Application(ApplicationSetting::read(limits, reader)?)),
            5 => Ok(Self::ProjectPolicy(ProjectPolicySetting::read(limits, reader)?)),
            6 => Ok(Self::Model(SettingNumber::read(limits, reader)?)),
            7 => Ok(Self::Worker(SettingNumber::read(limits, reader)?)),
            8 => Ok(Self::Provider(SettingNumber::read(limits, reader)?)),
            9 => Ok(Self::Limits),
            10..=u8::MAX => Err(Problem { path: paths::SETTING_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

