// Type: InboxObject.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum InboxObject {
    Question(InboxObjectQuestion),
    Proposal(InboxObjectProposal),
    Escalation(InboxObjectEscalation),
    PersonTask,
    Turn(InboxObjectTurn),
    Result(InboxObjectResult),
}

// Record: InboxObject.
impl Record for InboxObject {
    type Limits = Limits;
    const TAIL: Path = paths::INBOX_OBJECT_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2107)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2107)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Question(value) => { field::put(out, &[0], paths::INBOX_OBJECT_TAG)?; value.write(limits, out) },
            Self::Proposal(value) => { field::put(out, &[1], paths::INBOX_OBJECT_TAG)?; value.write(limits, out) },
            Self::Escalation(value) => { field::put(out, &[2], paths::INBOX_OBJECT_TAG)?; value.write(limits, out) },
            Self::PersonTask => field::put(out, &[3], paths::INBOX_OBJECT_TAG),
            Self::Turn(value) => { field::put(out, &[4], paths::INBOX_OBJECT_TAG)?; value.write(limits, out) },
            Self::Result(value) => { field::put(out, &[5], paths::INBOX_OBJECT_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::INBOX_OBJECT_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Question(InboxObjectQuestion::read(limits, reader)?)),
            1 => Ok(Self::Proposal(InboxObjectProposal::read(limits, reader)?)),
            2 => Ok(Self::Escalation(InboxObjectEscalation::read(limits, reader)?)),
            3 => Ok(Self::PersonTask),
            4 => Ok(Self::Turn(InboxObjectTurn::read(limits, reader)?)),
            5 => Ok(Self::Result(InboxObjectResult::read(limits, reader)?)),
            6..=u8::MAX => Err(Problem { path: paths::INBOX_OBJECT_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

