// Type: ReadPosition.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ReadPosition {
    pub task: u64,
    pub through: u64,
}

// Record: ReadPosition.
impl Record for ReadPosition {
    type Limits = Limits;
    const TAIL: Path = paths::READ_POSITION_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2398)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2398)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::write(field::U64, &self.task, limits, out, paths::READ_POSITION_TASK)?;
        field::write(field::U64, &self.through, limits, out, paths::READ_POSITION_THROUGH)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        Ok(Self {
            task: field::read(field::U64, limits, reader, paths::READ_POSITION_TASK)?,
            through: field::read(field::U64, limits, reader, paths::READ_POSITION_THROUGH)?,
        })
    }
}

