// Type: EndedGroup.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum EndedGroup {
    Rows(EndedRows),
    None,
}

// Record: EndedGroup.
impl Record for EndedGroup {
    type Limits = Limits;
    const TAIL: Path = paths::ENDED_GROUP_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2408)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2408)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Rows(value) => { field::put(out, &[0], paths::ENDED_GROUP_TAG)?; value.write(limits, out) },
            Self::None => field::put(out, &[1], paths::ENDED_GROUP_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::ENDED_GROUP_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Rows(EndedRows::read(limits, reader)?)),
            1 => Ok(Self::None),
            2..=u8::MAX => Err(Problem { path: paths::ENDED_GROUP_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

