// Type: LiveCall.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum LiveCall {
    Decoded(LiveCallDecoded),
    Raw(LiveCallRaw),
}

// Record: LiveCall.
impl Record for LiveCall {
    type Limits = Limits;
    const TAIL: Path = paths::LIVE_CALL_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2430)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2430)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Decoded(value) => { field::put(out, &[0], paths::LIVE_CALL_TAG)?; value.write(limits, out) },
            Self::Raw(value) => { field::put(out, &[1], paths::LIVE_CALL_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::LIVE_CALL_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Decoded(LiveCallDecoded::read(limits, reader)?)),
            1 => Ok(Self::Raw(LiveCallRaw::read(limits, reader)?)),
            2..=u8::MAX => Err(Problem { path: paths::LIVE_CALL_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

