// Type: ProposalAction.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ProposalAction {
    Batch(ProposalActionBatch),
    Effect(ProposalActionEffect),
    ProcedureEffect(ProposalActionProcedureEffect),
    Amend(Box<ProposalActionAmend>),
    Widen(ProposalActionWiden),
    Release(ProposalActionRelease),
    Settings(Box<ProposalActionSettings>),
}

// Record: ProposalAction.
impl Record for ProposalAction {
    type Limits = Limits;
    const TAIL: Path = paths::PROPOSAL_ACTION_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2490)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2490)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Batch(value) => { field::put(out, &[0], paths::PROPOSAL_ACTION_TAG)?; value.write(limits, out) },
            Self::Effect(value) => { field::put(out, &[1], paths::PROPOSAL_ACTION_TAG)?; value.write(limits, out) },
            Self::ProcedureEffect(value) => { field::put(out, &[2], paths::PROPOSAL_ACTION_TAG)?; value.write(limits, out) },
            Self::Amend(value) => { field::put(out, &[3], paths::PROPOSAL_ACTION_TAG)?; value.write(limits, out) },
            Self::Widen(value) => { field::put(out, &[4], paths::PROPOSAL_ACTION_TAG)?; value.write(limits, out) },
            Self::Release(value) => { field::put(out, &[5], paths::PROPOSAL_ACTION_TAG)?; value.write(limits, out) },
            Self::Settings(value) => { field::put(out, &[6], paths::PROPOSAL_ACTION_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::PROPOSAL_ACTION_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Batch(ProposalActionBatch::read(limits, reader)?)),
            1 => Ok(Self::Effect(ProposalActionEffect::read(limits, reader)?)),
            2 => Ok(Self::ProcedureEffect(ProposalActionProcedureEffect::read(limits, reader)?)),
            3 => Ok(Self::Amend(Box::new(ProposalActionAmend::read(limits, reader)?))),
            4 => Ok(Self::Widen(ProposalActionWiden::read(limits, reader)?)),
            5 => Ok(Self::Release(ProposalActionRelease::read(limits, reader)?)),
            6 => Ok(Self::Settings(Box::new(ProposalActionSettings::read(limits, reader)?))),
            7..=u8::MAX => Err(Problem { path: paths::PROPOSAL_ACTION_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

