// Type: GoalHolding.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum GoalHolding {
    Write(GoalHoldingWrite),
    Slot(GoalHoldingSlot),
}

// Record: GoalHolding.
impl Record for GoalHolding {
    type Limits = Limits;
    const TAIL: Path = paths::GOAL_HOLDING_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2609)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2609)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Write(value) => { field::put(out, &[0], paths::GOAL_HOLDING_TAG)?; value.write(limits, out) },
            Self::Slot(value) => { field::put(out, &[1], paths::GOAL_HOLDING_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::GOAL_HOLDING_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Write(GoalHoldingWrite::read(limits, reader)?)),
            1 => Ok(Self::Slot(GoalHoldingSlot::read(limits, reader)?)),
            2..=u8::MAX => Err(Problem { path: paths::GOAL_HOLDING_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

