#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Subject {
    Me,
    Task(SubjectTask),
    Tree(SubjectTree),
    Chips(SubjectChips),
    Inbox(SubjectInbox),
    Tasks(SubjectTasks),
    Run(SubjectRun),
    Deployment,
    Accounts,
    Settings,
    Terminal(SubjectTerminal),
}

// Record: Subject.
impl Record for Subject {
    type Limits = Limits;
    const TAIL: Path = paths::SUBJECT_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2701)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2701)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Me => field::put(out, &[0], paths::SUBJECT_TAG),
            Self::Task(value) => { field::put(out, &[1], paths::SUBJECT_TAG)?; value.write(limits, out) },
            Self::Tree(value) => { field::put(out, &[2], paths::SUBJECT_TAG)?; value.write(limits, out) },
            Self::Chips(value) => { field::put(out, &[3], paths::SUBJECT_TAG)?; value.write(limits, out) },
            Self::Inbox(value) => { field::put(out, &[4], paths::SUBJECT_TAG)?; value.write(limits, out) },
            Self::Tasks(value) => { field::put(out, &[5], paths::SUBJECT_TAG)?; value.write(limits, out) },
            Self::Run(value) => { field::put(out, &[6], paths::SUBJECT_TAG)?; value.write(limits, out) },
            Self::Deployment => field::put(out, &[7], paths::SUBJECT_TAG),
            Self::Accounts => field::put(out, &[8], paths::SUBJECT_TAG),
            Self::Settings => field::put(out, &[9], paths::SUBJECT_TAG),
            Self::Terminal(value) => { field::put(out, &[10], paths::SUBJECT_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::SUBJECT_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Me),
            1 => Ok(Self::Task(SubjectTask::read(limits, reader)?)),
            2 => Ok(Self::Tree(SubjectTree::read(limits, reader)?)),
            3 => Ok(Self::Chips(SubjectChips::read(limits, reader)?)),
            4 => Ok(Self::Inbox(SubjectInbox::read(limits, reader)?)),
            5 => Ok(Self::Tasks(SubjectTasks::read(limits, reader)?)),
            6 => Ok(Self::Run(SubjectRun::read(limits, reader)?)),
            7 => Ok(Self::Deployment),
            8 => Ok(Self::Accounts),
            9 => Ok(Self::Settings),
            10 => Ok(Self::Terminal(SubjectTerminal::read(limits, reader)?)),
            11..=u8::MAX => Err(Problem { path: paths::SUBJECT_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

