// Type: RunLocation.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum RunLocation {
    None,
    Connected(RunLocationConnected),
    Adrift(RunLocationAdrift),
}

// Record: RunLocation.
impl Record for RunLocation {
    type Limits = Limits;
    const TAIL: Path = paths::RUN_LOCATION_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2750)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2750)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::None => field::put(out, &[0], paths::RUN_LOCATION_TAG),
            Self::Connected(value) => { field::put(out, &[1], paths::RUN_LOCATION_TAG)?; value.write(limits, out) },
            Self::Adrift(value) => { field::put(out, &[2], paths::RUN_LOCATION_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::RUN_LOCATION_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::None),
            1 => Ok(Self::Connected(RunLocationConnected::read(limits, reader)?)),
            2 => Ok(Self::Adrift(RunLocationAdrift::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::RUN_LOCATION_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

