// Type: ProgramState.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ProgramState {
    Usable,
    NotSignedIn,
    SignedInOtherwise(ProgramOtherwise),
    Failed(ProgramFailed),
}

// Record: ProgramState.
impl Record for ProgramState {
    type Limits = Limits;
    const TAIL: Path = paths::PROGRAM_STATE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2771)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2771)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Usable => field::put(out, &[0], paths::PROGRAM_STATE_TAG),
            Self::NotSignedIn => field::put(out, &[1], paths::PROGRAM_STATE_TAG),
            Self::SignedInOtherwise(value) => { field::put(out, &[2], paths::PROGRAM_STATE_TAG)?; value.write(limits, out) },
            Self::Failed(value) => { field::put(out, &[3], paths::PROGRAM_STATE_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::PROGRAM_STATE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Usable),
            1 => Ok(Self::NotSignedIn),
            2 => Ok(Self::SignedInOtherwise(ProgramOtherwise::read(limits, reader)?)),
            3 => Ok(Self::Failed(ProgramFailed::read(limits, reader)?)),
            4..=u8::MAX => Err(Problem { path: paths::PROGRAM_STATE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

