// Type: LoginExit.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum LoginExit {
    Exited(LoginExitExited),
    Killed(LoginExitKilled),
    NotStarted,
}

// Record: LoginExit.
impl Record for LoginExit {
    type Limits = Limits;
    const TAIL: Path = paths::LOGIN_EXIT_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 3096)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 3096)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Exited(value) => { field::put(out, &[0], paths::LOGIN_EXIT_TAG)?; value.write(limits, out) },
            Self::Killed(value) => { field::put(out, &[1], paths::LOGIN_EXIT_TAG)?; value.write(limits, out) },
            Self::NotStarted => field::put(out, &[2], paths::LOGIN_EXIT_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::LOGIN_EXIT_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Exited(LoginExitExited::read(limits, reader)?)),
            1 => Ok(Self::Killed(LoginExitKilled::read(limits, reader)?)),
            2 => Ok(Self::NotStarted),
            3..=u8::MAX => Err(Problem { path: paths::LOGIN_EXIT_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

