// Type: LoginEnd.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum LoginEnd {
    SignedIn(LoginEndSignedIn),
    NotFinished(LoginEndNotFinished),
    Cancelled,
    Refused(LoginEndRefused),
}

// Record: LoginEnd.
impl Record for LoginEnd {
    type Limits = Limits;
    const TAIL: Path = paths::LOGIN_END_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 3268)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 3268)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::SignedIn(value) => { field::put(out, &[0], paths::LOGIN_END_TAG)?; value.write(limits, out) },
            Self::NotFinished(value) => { field::put(out, &[1], paths::LOGIN_END_TAG)?; value.write(limits, out) },
            Self::Cancelled => field::put(out, &[2], paths::LOGIN_END_TAG),
            Self::Refused(value) => { field::put(out, &[3], paths::LOGIN_END_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::LOGIN_END_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::SignedIn(LoginEndSignedIn::read(limits, reader)?)),
            1 => Ok(Self::NotFinished(LoginEndNotFinished::read(limits, reader)?)),
            2 => Ok(Self::Cancelled),
            3 => Ok(Self::Refused(LoginEndRefused::read(limits, reader)?)),
            4..=u8::MAX => Err(Problem { path: paths::LOGIN_END_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

