// Type: SettingHosts.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum SettingHosts {
    Workers,
    Engine,
    Both,
}

// Record: SettingHosts.
impl Record for SettingHosts {
    type Limits = Limits;
    const TAIL: Path = paths::SETTING_HOSTS_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 3478)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 3478)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Workers => field::put(out, &[0], paths::SETTING_HOSTS_TAG),
            Self::Engine => field::put(out, &[1], paths::SETTING_HOSTS_TAG),
            Self::Both => field::put(out, &[2], paths::SETTING_HOSTS_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::SETTING_HOSTS_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Workers),
            1 => Ok(Self::Engine),
            2 => Ok(Self::Both),
            3..=u8::MAX => Err(Problem { path: paths::SETTING_HOSTS_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

